// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, getLinksSearch, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const q = "zzznosuchtokenzzz";
    const tag = "skyramp-search-tag-a";

    const collectionsPostResponse = await createCollection(client, headers, "Skyramp Search Collection");

    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Skyramp Search Collection");
    expect(getResponseValue(collectionsPostResponse, "response.isPublic"), 'isPublic').toBe(false);
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const collectionId = getResponseValue(collectionsPostResponse, "response.id");

    const linksPostResponse = await createLink(
        client,
        headers,
        collectionId,
        "Skyramp Search Alpha Doc",
        "https://example.com/urlmarkeralpha",
        "descmarkeralpha notes",
        [{ name: "skyramp-search-tag-a" }]
    );

    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Skyramp Search Alpha Doc");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/urlmarkeralpha");
    expect(getResponseValue(linksPostResponse, "response.description"), 'description').toBe("descmarkeralpha notes");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(collectionId);
    expect(getResponseValue(linksPostResponse, "response.tags.0.name"), 'tags.0.name').toBe("skyramp-search-tag-a");
    expect(getResponseValue(linksPostResponse, "response.tags.1"), 'tags.1').toBeNull();
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const alphaLinkId = getResponseValue(linksPostResponse, "response.id");

    const linksPost1Response = await createLink(
        client,
        headers,
        collectionId,
        "Skyramp Search Beta Doc",
        "https://example.com/urlmarkerbeta",
        "descmarkerbeta notes",
        [{ name: "skyramp-search-tag-b" }]
    );

    expect(linksPost1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPost1Response, "response.name"), 'name').toBe("Skyramp Search Beta Doc");
    expect(getResponseValue(linksPost1Response, "response.url"), 'url').toBe("https://example.com/urlmarkerbeta");
    expect(getResponseValue(linksPost1Response, "response.description"), 'description').toBe("descmarkerbeta notes");
    expect(getResponseValue(linksPost1Response, "response.collectionId"), 'collectionId').toBe(collectionId);
    expect(getResponseValue(linksPost1Response, "response.tags.0.name"), 'tags.0.name').toBe("skyramp-search-tag-b");
    expect(getResponseValue(linksPost1Response, "response.tags.1"), 'tags.1').toBeNull();
    expect(getResponseValue(linksPost1Response, "response.id"), 'id').toBeGreaterThan(0);

    const betaLinkId = getResponseValue(linksPost1Response, "response.id");

    const [searchGetResponse, searchGet1Response, searchGet2Response, searchGet3Response, searchGet4Response, searchGet5Response, searchGet6Response] = await Promise.all([
        getLinksSearch(client, headers),
        getLinksSearch(client, headers, {"q": ["Skyramp Search"]}),
        getLinksSearch(client, headers, {"q": ["urlmarkeralpha"]}),
        getLinksSearch(client, headers, {"q": ["descmarkerbeta"]}),
        getLinksSearch(client, headers, {"tag": [tag]}),
        getLinksSearch(client, headers, {"q": ["Beta"], "tag": [tag]}),
        getLinksSearch(client, headers, {"q": [q]}),
    ]);

    // Both filters omitted: the caller's links come back, capped at 50.
    expect(searchGetResponse.statusCode, 'status code').toBe(200);
    const unfilteredLinks = getResponseValue(searchGetResponse, "response");
    expect(Array.isArray(unfilteredLinks), 'response is an array').toBe(true);
    expect(unfilteredLinks.length, 'response length is capped at 50').toBeLessThanOrEqual(50);
    expect(unfilteredLinks.map((link: any) => link.id), 'unfiltered ids').toContain(alphaLinkId);
    expect(unfilteredLinks.map((link: any) => link.id), 'unfiltered ids').toContain(betaLinkId);

    // ?q matches the name of both links; the newest one is first.
    expect(searchGet1Response.statusCode, 'status code').toBe(200);
    const nameMatches = getResponseValue(searchGet1Response, "response");
    expect(nameMatches.length, 'name matches length').toBe(2);
    expect(nameMatches.map((link: any) => link.id), 'name match ids').toContain(alphaLinkId);
    expect(nameMatches.map((link: any) => link.id), 'name match ids').toContain(betaLinkId);
    expect(getResponseValue(searchGet1Response, "response.2"), 'response.2').toBeNull();
    expect(
        new Date(getResponseValue(searchGet1Response, "response.0.createdAt")).getTime(),
        'results are ordered newest first'
    ).toBeGreaterThanOrEqual(new Date(getResponseValue(searchGet1Response, "response.1.createdAt")).getTime());

    // ?q matches a token that only Alpha's url carries.
    expect(searchGet2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(searchGet2Response, "response").length, 'url match length').toBe(1);
    expect(getResponseValue(searchGet2Response, "response.0.id"), 'url match id').toBe(alphaLinkId);
    expect(getResponseValue(searchGet2Response, "response.0.name"), 'url match name').toBe("Skyramp Search Alpha Doc");
    expect(getResponseValue(searchGet2Response, "response.0.url"), 'url match url').toBe("https://example.com/urlmarkeralpha");
    expect(getResponseValue(searchGet2Response, "response.0.collection.name"), 'url match collection').toBe("Skyramp Search Collection");
    expect(getResponseValue(searchGet2Response, "response.1"), 'response.1').toBeNull();

    // ?q matches a token that only Beta's description carries.
    expect(searchGet3Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(searchGet3Response, "response").length, 'description match length').toBe(1);
    expect(getResponseValue(searchGet3Response, "response.0.id"), 'description match id').toBe(betaLinkId);
    expect(getResponseValue(searchGet3Response, "response.0.description"), 'description match description').toBe("descmarkerbeta notes");
    expect(getResponseValue(searchGet3Response, "response.1"), 'response.1').toBeNull();

    // ?tag by exact tag name returns Alpha only.
    expect(searchGet4Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(searchGet4Response, "response").length, 'tag match length').toBe(1);
    expect(getResponseValue(searchGet4Response, "response.0.id"), 'tag match id').toBe(alphaLinkId);
    expect(getResponseValue(searchGet4Response, "response.0.name"), 'tag match name').toBe("Skyramp Search Alpha Doc");
    expect(getResponseValue(searchGet4Response, "response.0.tags.0.name"), 'tag match tag name').toBe(tag);
    expect(getResponseValue(searchGet4Response, "response.0.tags.1"), 'tags.1').toBeNull();
    expect(getResponseValue(searchGet4Response, "response.1"), 'response.1').toBeNull();

    // ?q and ?tag match different links, so AND semantics yield nothing.
    expect(searchGet5Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(searchGet5Response, "response").length, 'AND match length').toBe(0);
    expect(getResponseValue(searchGet5Response, "response.0"), 'response.0').toBeNull();
    expect(getResponseValue(searchGet5Response, "error"), 'error carries no value').toBeNull();

    // A token no record carries returns an empty array, not 404.
    expect(searchGet6Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(searchGet6Response, "response").length, 'no-match length').toBe(0);
    expect(getResponseValue(searchGet6Response, "response.0"), 'response.0').toBeNull();
    expect(getResponseValue(searchGet6Response, "error"), 'error carries no value').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, headers, alphaLinkId);
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted id').toBe(alphaLinkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'deleted name').toBe("Skyramp Search Alpha Doc");

    const linksLinksDelete1Response = await deleteLink(client, headers, betaLinkId);
    expect(linksLinksDelete1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDelete1Response, "response.id"), 'deleted id').toBe(betaLinkId);
    expect(getResponseValue(linksLinksDelete1Response, "response.name"), 'deleted name').toBe("Skyramp Search Beta Doc");

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, headers, collectionId);
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted id').toBe(collectionId);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.name"), 'deleted name').toBe("Skyramp Search Collection");
});
